/** Released Storage emitter with deterministic sprites; geometry/UV/flags, not a rendered-window claim. */
public final class StorageModelLegacyOracle {
 private static final int[] MASKS={0,1,2,4,8,16,32,21,42,63};
 private static IBakedModel delegate(final java.util.function.Function<String,TextureAtlasSprite> sprites){return new IBakedModel(){public List<BakedQuad> getQuads(IBlockState state,EnumFacing face,long seed){return Collections.emptyList();}public boolean isAmbientOcclusion(){return false;}public boolean isGui3d(){return true;}public boolean isBuiltInRenderer(){return false;}public TextureAtlasSprite getParticleTexture(){return sprites.apply("vandorlabs:blocks/storage/cabinet_front");}public ItemCameraTransforms getItemCameraTransforms(){return ItemCameraTransforms.DEFAULT;}public ItemOverrideList getOverrides(){return ItemOverrideList.NONE;}};}
 private static JsonArray ints(int[] values){JsonArray a=new JsonArray();for(int v:values)a.add(v);return a;}
 private static JsonObject quad(BakedQuad quad){JsonObject row=new JsonObject();row.addProperty("face",quad.getFace().getIndex());row.addProperty("sprite",quad.getSprite().getIconName());row.addProperty("shade",quad.shouldApplyDiffuseLighting());row.addProperty("tint",quad.getTintIndex());JsonArray points=new JsonArray();int[] data=quad.getVertexData();int stride=data.length/4,color=quad.getFormat().getColorOffset()/4,uv=quad.getFormat().getUvOffsetById(0)/4;for(int i=0;i<4;i++){if(data[i*stride+color]!=-1)throw new AssertionError("Source Storage vertex color");JsonArray p=new JsonArray();for(int axis=0;axis<3;axis++)p.add(Float.intBitsToFloat(data[i*stride+axis]));p.add(quad.getSprite().getUnInterpolatedU(Float.intBitsToFloat(data[i*stride+uv]))/16F);p.add(quad.getSprite().getUnInterpolatedV(Float.intBitsToFloat(data[i*stride+uv+1]))/16F);points.add(p);}row.add("points",points);return row;}
 public static void main(String[] args)throws Exception {
  net.minecraft.init.Bootstrap.register();List<Integer> choices=new ArrayList<>();JsonArray sets=new JsonArray();for(int i=0;i<ScreenHousingTextures.BUILTIN_COUNT;i++)if(ScreenHousingTextures.category(i).equals("Storage")){choices.add(i);JsonObject set=new JsonObject();set.addProperty("choice",i);JsonArray faces=new JsonArray();for(EnumFacing f:EnumFacing.values())faces.add(ScreenHousingTextures.storageTexture(i,f));set.add("faces",faces);sets.add(set);}if(choices.size()!=14)throw new AssertionError("Source Storage sets");choices.add(0);choices.add(7);
  int[] mixed={-1,ScreenHousingTextures.DEFAULT_STORAGE,7,-1,0,ScreenHousingTextures.DEFAULT_STORAGE+1};FaceTextures[] patterns={FaceTextures.DEFAULT,new FaceTextures(true,new int[]{-1,-1,-1,-1,-1,-1}),new FaceTextures(true,mixed),new FaceTextures(false,mixed)};JsonObject header=new JsonObject();header.addProperty("schema",1);header.add("sets",sets);JsonArray pp=new JsonArray();for(FaceTextures p:patterns){JsonObject pattern=new JsonObject();pattern.addProperty("enabled",p.enabled);pattern.add("faces",ints(p.choices()));pp.add(pattern);}header.add("patterns",pp);header.addProperty("ambient",false);
  Path output=Paths.get("build/test-artifacts/storage-model-source-reference.jsonl");Files.createDirectories(output.getParent());java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");int profiles=0,quads=0;try(BufferedWriter out=new BufferedWriter(new OutputStreamWriter(new java.security.DigestOutputStream(Files.newOutputStream(output),digest),"UTF-8"))){out.write(header.toString());out.newLine();for(int aspect=0;aspect<3;aspect++){final int shape=aspect;Map<String,TextureAtlasSprite> atlas=new HashMap<>();java.util.function.Function<String,TextureAtlasSprite> sprites=name->atlas.computeIfAbsent(name,key->{TextureAtlasSprite sprite=new TextureAtlasSprite(key){};sprite.setIconWidth(shape==2?32:16);sprite.setIconHeight(shape==1?32:16);int cell=Math.floorMod(key.hashCode(),64);sprite.initSprite(1024,1024,cell%8*64,cell/8*64,false);return sprite;});ProgrammableHousingModel model=new ProgrammableHousingModel(delegate(sprites),false,true,sprites);if(model.isAmbientOcclusion())throw new AssertionError("Source Storage ambient lighting");
   for(int main:choices)for(EnumFacing facing:EnumFacing.HORIZONTALS)for(int layout=0;layout<3;layout++)for(int pattern=0;pattern<patterns.length;pattern++)for(int mask:MASKS){IExtendedBlockState state=((IExtendedBlockState)ModBlocks.PROGRAMMABLE_STORAGE.getDefaultState().withProperty(BlockAnimatedScreenSelector.FACING,facing)).withProperty(ProgrammableHousingState.FINISH,main).withProperty(ProgrammableHousingState.SIDE_FINISH,-1).withProperty(ProgrammableHousingState.FACES,patterns[pattern]).withProperty(ProgrammableHousingState.TILE_SIDES,layout).withProperty(ProgrammableHousingState.VISIBLE,mask);JsonObject row=new JsonObject();row.addProperty("aspect",aspect);row.addProperty("main",main);row.addProperty("facing",facing.getIndex());row.addProperty("layout",layout);row.addProperty("pattern",pattern);row.addProperty("visible",mask);JsonArray qq=new JsonArray();for(BakedQuad q:model.getQuads(state,null,0)){qq.add(quad(q));quads++;}for(EnumFacing face:EnumFacing.values())if(!model.getQuads(state,face,0).isEmpty())throw new AssertionError("Source side bucket duplication");row.add("quads",qq);out.write(row.toString());out.newLine();profiles++;}
  }}long bytes=Files.size(output);if(bytes>64*1024*1024||profiles!=23040)throw new AssertionError("Storage emitter corpus bound/coverage");StringBuilder hash=new StringBuilder();for(byte b:digest.digest())hash.append(String.format("%02x",b&255));if(!hash.toString().equals("ea12d290a49eaf61da0234a78fbd37a9ba7455f245c4b038e639bf5818fc3948"))throw new AssertionError("Source Storage emitter changed "+hash);System.out.println("Actual Storage model PASS profiles="+profiles+" quads="+quads+" sets="+sets.size()+" bytes="+bytes+" sha256="+hash);
 }
}
